      area: $json.body.area,
      year: parseInt($json.body.year),
      version: parseInt($json.body.version),
      notes: $json.body.notes
    }
  }
];

// Função UUID compatível com n8n
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

return [
  {
    json: {
      // ID interno do documento
      id: uuidv4(),

      // ===== METADADOS DO FORMULÁRIO =====
      title: $json.title,
      type: $json.type,
      source: $json.source,
      area: $json.area,
      year: $json.year ? parseInt($json.year) : null,
      version: $json.version ? parseInt($json.version) : 1,
      notes: $json.notes || null,

      // ===== DADOS DO GOOGLE DRIVE =====
      file_name: $json.name,
      drive_file_id: $json.id,
      drive_url: $json.webViewLink,
      mime_type: $json.mimeType || null,

      // ===== CONTROLE DO SISTEMA =====
      status: 'INDEXING',
      created_at: new Date().toISOString()
    }
  }
];

const where = [];
const query = $json.query || {};

if (query.type) {
  where.push(`type = '${query.type}'`);
}

if (query.area) {
  where.push(`area = '${query.area}'`);
}

if (query.status) {
  where.push(`status = '${query.status}'`);
}

const whereClause = where.length
  ? `WHERE ${where.join(' AND ')}`
  : '';

return [
  {
    json: {
      whereClause
    }
  }
];

// Nome original do arquivo
const fullName = $json.name;

// Regex para capturar o conteúdo entre [ ]
const match = fullName.match(/\[(.*?)\]/);

if (!match) {
  throw new Error('Nome do arquivo não segue o padrão esperado');
}

// Divide os metadados
const parts = match[1].split(',').map(p => p.trim());

return [
  {
    json: {
      // Metadados extraídos
      title: parts[0] || null,
      type: parts[1] || null,
      source: parts[2] || null,
      area: parts[3] || null,
      year: parts[4] ? parseInt(parts[4]) : null,

      // Nome do arquivo
      file_name: fullName,

      // Opcional: nome limpo para exibição
      clean_title: parts[0],

      // Debug opcional
      raw_metadata: parts
    }
  }
];

const files = $items("Search files and folders");

const driveIds = files
  .map(item => item.json.id)
  .filter(Boolean);

return [
  {
    json: {
      driveIds
    }
  }
];

// 1️⃣ Buscar os IDs vindos do Drive
